/**
 * serve-sim's input protocol, and the translation from the browser client's
 * messages into it.
 *
 * serve-sim does not take JSON text on a bare `/ws`. Its input socket is
 * `/helper/<udid>/ws` on the preview port, and every message is ONE binary frame:
 *
 *   byte 0      a tag (3 = touch, 4 = button, 6 = key, 11 = scroll, ...)
 *   bytes 1..n  UTF-8 JSON for that tag
 *
 *   3  touch   {type: "begin" | "move" | "end", x, y}     x, y normalized 0..1
 *   6  key     {type: "down" | "up", usage}                USB HID usage (page 7)
 *   11 scroll  {dx, dy, x, y}                              dx, dy as a fraction of the screen
 *
 * (Read from serve-sim 0.1.48's own CLI and preview UI: `serve-sim tap`, `serve-sim type`
 * and the viewer send exactly these frames.) Anything serve-sim does not
 * understand is dropped without a reply, which is why a wrong path or a wrong
 * format looks like "input does nothing" and the Event Log stays at 0.
 */

const TAG = Object.freeze({ TOUCH: 3, BUTTON: 4, MULTI_TOUCH: 5, KEY: 6, SCROLL: 11 });

/** Highest tag serve-sim uses today; binary frames with a tag in 1..MAX pass through. */
const MAX_NATIVE_TAG = 31;

function frame(tag, payload) {
  const json = Buffer.from(JSON.stringify(payload), 'utf8');
  return Buffer.concat([Buffer.from([tag]), json]);
}

const clamp01 = (n) => Math.max(0, Math.min(1, Number(n) || 0));

// KeyboardEvent.code -> USB HID keyboard usage (page 0x07).
const CODE_TO_USAGE = (() => {
  const m = {};
  for (let i = 0; i < 26; i++) m[`Key${String.fromCharCode(65 + i)}`] = 4 + i;
  for (let i = 1; i <= 9; i++) m[`Digit${i}`] = 29 + i;
  m.Digit0 = 39;
  Object.assign(m, {
    Enter: 40, NumpadEnter: 40, Escape: 41, Backspace: 42, Tab: 43, Space: 44,
    Minus: 45, Equal: 46, BracketLeft: 47, BracketRight: 48, Backslash: 49,
    Semicolon: 51, Quote: 52, Backquote: 53, Comma: 54, Period: 55, Slash: 56,
    CapsLock: 57,
    F1: 58, F2: 59, F3: 60, F4: 61, F5: 62, F6: 63, F7: 64, F8: 65, F9: 66, F10: 67, F11: 68, F12: 69,
    Insert: 73, Home: 74, PageUp: 75, Delete: 76, End: 77, PageDown: 78,
    ArrowRight: 79, ArrowLeft: 80, ArrowDown: 81, ArrowUp: 82,
    ControlLeft: 224, ShiftLeft: 225, AltLeft: 226, MetaLeft: 227,
    ControlRight: 228, ShiftRight: 229, AltRight: 230, MetaRight: 231,
  });
  return m;
})();

// Printable ASCII character -> {usage, shift}, US layout (what serve-sim's `type` uses).
const CHAR_TO_KEY = (() => {
  const m = {};
  for (let i = 0; i < 26; i++) {
    m[String.fromCharCode(97 + i)] = { usage: 4 + i, shift: false };
    m[String.fromCharCode(65 + i)] = { usage: 4 + i, shift: true };
  }
  const digits = '1234567890';
  const shifted = '!@#$%^&*()';
  for (let i = 0; i < 10; i++) {
    m[digits[i]] = { usage: 30 + i, shift: false };
    m[shifted[i]] = { usage: 30 + i, shift: true };
  }
  for (const [plain, shift, usage] of [
    ['-', '_', 45], ['=', '+', 46], ['[', '{', 47], [']', '}', 48], ['\\', '|', 49],
    [';', ':', 51], ["'", '"', 52], ['`', '~', 53], [',', '<', 54], ['.', '>', 55], ['/', '?', 56],
  ]) {
    m[plain] = { usage, shift: false };
    m[shift] = { usage, shift: true };
  }
  m[' '] = { usage: 44, shift: false };
  m['\n'] = { usage: 40, shift: false };
  m['\t'] = { usage: 43, shift: false };
  return m;
})();

const SHIFT = 225;

function keyUsage(msg) {
  if (msg.code && CODE_TO_USAGE[msg.code] != null) return CODE_TO_USAGE[msg.code];
  if (typeof msg.key === 'string') {
    if (CODE_TO_USAGE[msg.key] != null) return CODE_TO_USAGE[msg.key]; // "Enter", "Backspace", ...
    if (msg.key.length === 1 && CHAR_TO_KEY[msg.key]) return CHAR_TO_KEY[msg.key].usage;
  }
  return null;
}

function textToKeyFrames(text) {
  const frames = [];
  for (const ch of String(text)) {
    if (ch === '\r') continue;
    const k = CHAR_TO_KEY[ch];
    if (!k) continue; // serve-sim's HID keyboard is US-only; skip what it cannot type
    if (k.shift) frames.push(frame(TAG.KEY, { type: 'down', usage: SHIFT }));
    frames.push(frame(TAG.KEY, { type: 'down', usage: k.usage }));
    frames.push(frame(TAG.KEY, { type: 'up', usage: k.usage }));
    if (k.shift) frames.push(frame(TAG.KEY, { type: 'up', usage: SHIFT }));
  }
  return frames;
}

const POINTER_PHASE = { down: 'begin', move: 'move', up: 'end', cancel: 'end' };

/**
 * Translate one message from a browser DataChannel (or the signaling socket)
 * into zero or more serve-sim frames.
 *
 * - A binary message whose first byte is a serve-sim tag is already native
 *   (the v1 client relays serve-sim's own UI frames) and passes through as is.
 * - The v2 client's JSON (pointer / keyboard / scroll / clipboard) is translated.
 * - Everything else (control messages, telemetry, unknown) returns [].
 */
function toServeSimFrames(raw) {
  if (raw == null) return [];
  let buf;
  if (Buffer.isBuffer(raw)) buf = raw;
  else if (raw instanceof ArrayBuffer) buf = Buffer.from(raw);
  else if (ArrayBuffer.isView(raw)) buf = Buffer.from(raw.buffer, raw.byteOffset, raw.byteLength);
  else buf = Buffer.from(String(raw), 'utf8');
  if (buf.length === 0) return [];

  const first = buf[0];
  if (first >= 1 && first <= MAX_NATIVE_TAG) return [buf];

  let msg;
  try { msg = JSON.parse(buf.toString('utf8')); } catch { return []; }
  if (!msg || typeof msg !== 'object') return [];

  switch (msg.type) {
    case 'pointer': {
      const phase = POINTER_PHASE[msg.event];
      if (!phase) return [];
      // One finger: secondary pointers (a second touch on a touchscreen) are ignored.
      if (msg.pointerId != null && msg.isPrimary === false) return [];
      return [frame(TAG.TOUCH, { type: phase, x: clamp01(msg.x), y: clamp01(msg.y) })];
    }
    case 'keyboard': {
      if (msg.isComposing) return [];
      const type = msg.event === 'keydown' ? 'down' : msg.event === 'keyup' ? 'up' : null;
      const usage = keyUsage(msg);
      if (!type || usage == null) return [];
      return [frame(TAG.KEY, { type, usage })];
    }
    case 'scroll': {
      let dx = Number(msg.dx);
      let dy = Number(msg.dy);
      if (!Number.isFinite(dx) || !Number.isFinite(dy)) {
        // Older clients send raw wheel pixels; assume a phone-sized viewport.
        dx = (Number(msg.deltaX) || 0) / 390;
        dy = (Number(msg.deltaY) || 0) / 844;
      }
      if (dx === 0 && dy === 0) return [];
      const x = msg.x == null ? 0.5 : clamp01(msg.x);
      const y = msg.y == null ? 0.5 : clamp01(msg.y);
      return [frame(TAG.SCROLL, { dx, dy, x, y })];
    }
    case 'clipboard':
      return msg.text ? textToKeyFrames(msg.text) : [];
    default:
      return [];
  }
}

/** True for a touch "move" frame (the only kind worth coalescing while offline). */
function isTouchMoveFrame(buf) {
  if (!Buffer.isBuffer(buf) || buf[0] !== TAG.TOUCH) return false;
  try { return JSON.parse(buf.subarray(1).toString('utf8')).type === 'move'; } catch { return false; }
}

/**
 * The player sends touch moves on an unordered, unreliable DataChannel (a late
 * move is worthless; a retransmitted one only adds lag) and begin/end on an
 * ordered, reliable one (a lost "end" is a finger stuck on the screen). Across
 * two channels a move can arrive after its "end" or before its "begin";
 * serve-sim would read that as a touch without a begin. This guard, one per
 * browser session, drops such moves by the client's sequence numbers.
 */
class TouchOrderGuard {
  constructor() {
    this.down = false;
    this.lastPhaseSeq = -Infinity;
    this.dropped = 0;
  }

  /** @returns {boolean} false when this raw message is a stale or orphan move to drop. */
  accept(raw) {
    let msg;
    try {
      const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw);
      if (text[0] !== '{') return true;
      msg = JSON.parse(text);
    } catch { return true; }
    if (!msg || msg.type !== 'pointer' || msg.isPrimary === false) return true;
    const seq = Number.isFinite(msg.seq) ? msg.seq : null;
    if (msg.event === 'down') {
      this.down = true;
      if (seq !== null) this.lastPhaseSeq = seq;
      return true;
    }
    if (msg.event === 'up' || msg.event === 'cancel') {
      this.down = false;
      if (seq !== null) this.lastPhaseSeq = seq;
      return true;
    }
    if (msg.event === 'move') {
      if (!this.down || (seq !== null && seq < this.lastPhaseSeq)) {
        this.dropped++;
        return false;
      }
    }
    return true;
  }
}

/**
 * serve-sim's input socket lives next to its stream: `/helper/<udid>/stream.mjpeg`
 * -> `/helper/<udid>/ws`. An explicit path always wins.
 */
function inputPathFor({ inputPath, streamPath } = {}) {
  if (inputPath) return inputPath.startsWith('/') ? inputPath : `/${inputPath}`;
  const pathOnly = String(streamPath || '').split('?')[0];
  const m = /^(.*)\/stream\.(?:mjpeg|avcc)$/.exec(pathOnly);
  if (m && m[1]) return `${m[1]}/ws`;
  return '/ws';
}

module.exports = {
  TAG,
  CODE_TO_USAGE,
  toServeSimFrames,
  textToKeyFrames,
  isTouchMoveFrame,
  inputPathFor,
  TouchOrderGuard,
};
